'use strict';
const discovery={docs:[],indexing:false,indexPromise:null,generation:0,skipped:0,graphQuery:'',selected:null,linked:false};
const docId=d=>d.id||d.path;
function discoveryDocs(){if(workbench.source!=='project')return vault.notes;if(workbench.file?.kind==='markdown'){const current=discovery.docs.find(d=>d.path===workbench.file.path);if(current)current.body=workbench.file.body}return discovery.docs}
async function indexProject(force=false){if(!workbench.project)return;if(discovery.indexPromise&&!force)return discovery.indexPromise;const generation=++discovery.generation,files=projectFiles();discovery.indexing=true;discovery.skipped=0;discovery.docs=files.map(f=>({...f,id:f.path,title:f.name.replace(/\.(md|markdown)$/i,''),body:'',tags:[]}));
 const task=(async()=>{let bytes=0;for(const doc of discovery.docs){if(generation!==discovery.generation)return;if(doc.kind!=='markdown')continue;if(bytes>=40*1024*1024){discovery.skipped++;continue}const result=await window.projectAdapter.read(doc.path);if(generation!==discovery.generation)return;if(result.error){discovery.skipped++;continue}bytes+=result.size;Object.assign(doc,result)}if(generation!==discovery.generation)return;discovery.indexing=false;discovery.indexPromise=null;refreshSearchResults();if(state.view==='graph')renderUniverse()})();discovery.indexPromise=task;return task}
const oldProjectOpen=openProject,oldProjectRefresh=refreshProject;
openProject=async()=>{const previous=workbench.project;await oldProjectOpen();if(workbench.project!==previous)indexProject(true)};
refreshProject=async()=>{await oldProjectRefresh();indexProject(true)};
workActions.open=openProject;workActions.refresh=refreshProject;actions['open-project']=openProject;
function queryHelp(){return '<span>Combine filtros: <code>#tag @menção after:2026-01-01</code></span>'}
function filterChips(query){return AmagoSearch.tokens(query).map((t,i)=>`<button class="query-chip" data-remove-filter="${i}" title="Remover filtro">${esc(t.raw)} ×</button>`).join('')}
function searchSummary(){return discovery.indexing?'Indexando conteúdo local…':workbench.source==='project'&&discovery.skipped?`${discovery.skipped} arquivo(s) sem índice de conteúdo · busca por nome disponível`:'Nome, conteúdo, tags, menções e data'}
searchResults=function(){const docs=discoveryDocs().filter(d=>(!workbench.filter||d.kind===workbench.filter)&&AmagoSearch.matches(d,workbench.query));return `<div class="search-result-count">${docs.length} resultado${docs.length===1?'':'s'}</div>`+docs.map(d=>{const meta=AmagoSearch.documentData(d);return `<button class="side-result" ${workbench.source==='project'?`data-project-file="${esc(d.path)}"`:`data-note="${esc(d.id)}"`}>${icon(fileLabel(d.kind||'markdown'))}<span>${esc(d.title||d.name)}<small>${esc(d.path||d.folder)}${meta.tags.length?' · #'+esc(meta.tags.slice(0,2).join(' #')):''}</small><small>${esc((d.body||'').replace(/^---[\s\S]*?---\s*/,'').slice(0,95))}</small></span></button>`}).join('')||'<p class="side-empty">Nenhum resultado. Remova um filtro para ampliar a busca.</p>'};
function refreshSearchResults(){if($('#side-results'))$('#side-results').innerHTML=searchResults();if($('#query-chips'))$('#query-chips').innerHTML=filterChips(workbench.query);if($('#index-state'))$('#index-state').textContent=searchSummary()}
const discoveryTree=renderTree;
renderTree=function(){discoveryTree();if(workbench.source==='project')$('.project-location')?.insertAdjacentHTML('afterend',`<button class="project-map-button" data-open-universe>${icon('graph')}Mapa do projeto</button>`);if(workbench.tab!=='search')return;$('#side-query').placeholder='Texto, #tag, @menção…';$('#side-query').setAttribute('aria-label','Busca híbrida');$('.side-search-caption').outerHTML=`<div class="hybrid-help">${queryHelp()}</div><div class="query-chips" id="query-chips">${filterChips(workbench.query)}</div><details class="search-filters"><summary>Refinar busca</summary><form id="filter-builder"><label>Tag<input name="tag" placeholder="projeto"></label><label>Menção<input name="mention" placeholder="Pessoa ou [[nota]]"></label><label>A partir de<input name="after" type="date"></label><label>Até<input name="before" type="date"></label><button class="plain-button">Aplicar filtros</button></form></details><p class="index-state" id="index-state">${searchSummary()}</p>`;$('#side-query').addEventListener('input',refreshSearchResults);$('#filter-builder').onsubmit=e=>{e.preventDefault();const values=new FormData(e.target);for(const [key,value] of values)if(value)workbench.query+=' '+key+':"'+String(value).replaceAll('"','')+'"';workbench.query=workbench.query.trim();renderTree()};if(workbench.source==='project'&&!discovery.docs.length&&!discovery.indexing)indexProject()};
function graphPreferences(){vault.graphLayouts??={};const key=workbench.source==='project'?'project:'+workbench.project.root:'personal';return vault.graphLayouts[key]??=( {positions:{},width:1.4,size:7} )}
function resolveLink(docs,source,link){const norm=AmagoSearch.normalize,clean=x=>norm(x.replace(/\.(md|markdown)$/i,'')),target=clean(link),relative=source.path?clean(source.path.split('/').slice(0,-1).concat(link).join('/')):'';return (relative?docs.find(d=>d.path&&clean(d.path)===relative):null)||docs.find(d=>d.path&&clean(d.path)===target)||docs.find(d=>clean(d.title||d.name||'')===target)}
function graphData(){const all=discoveryDocs().filter(d=>!d.kind||d.kind==='markdown'),edges=[];for(const source of all)for(const link of AmagoSearch.metadata(source.body).links){const target=resolveLink(all,source,link);if(target&&docId(target)!==docId(source)&&!edges.some(e=>(e.a===docId(source)&&e.b===docId(target))||(e.b===docId(source)&&e.a===docId(target))))edges.push({a:docId(source),b:docId(target)})}const connected=new Set(edges.flatMap(e=>[e.a,e.b]));const filtered=all.filter(d=>AmagoSearch.matches(d,discovery.graphQuery)&&(!discovery.linked||connected.has(docId(d))));const docs=filtered.slice(0,500),ids=new Set(docs.map(docId));return {docs,edges:edges.filter(e=>ids.has(e.a)&&ids.has(e.b)),total:filtered.length}}
let graphPan={x:0,y:0,zoom:1};
function renderUniverse(){const {docs,edges,total}=graphData(),prefs=graphPreferences();$('#crumb-workspace').textContent=workbench.source==='project'?workbench.project.name:'Meu universo';$('#crumb-folder').textContent='Mapa de conexões';$('#main').innerHTML=`<section class="universe-page"><div class="universe-heading"><div><div class="eyebrow">ATLAS DE IDEIAS</div><h1>Um universo de conexões</h1></div><span class="universe-count">${docs.length} pontos · ${edges.length} vínculos${discovery.indexing?' · indexando…':''}</span></div><div class="universe-filter"><div class="side-search">${icon('search')}<input id="graph-query" value="${esc(discovery.graphQuery)}" placeholder="Texto, #tag, @menção, after:2026-01-01…" aria-label="Busca híbrida no mapa"></div><button class="plain-button" id="use-sidebar-query">Usar busca lateral</button><label class="connected-only"><input id="linked-only" type="checkbox" ${discovery.linked?'checked':''}>Com vínculos</label></div><div class="query-chips" id="graph-chips">${filterChips(discovery.graphQuery)}</div><div class="universe-toolbar"><label>Traçado <input id="edge-width" aria-label="Espessura dos vínculos" type="range" min="0.5" max="5" step="0.1" value="${prefs.width}"></label><label>Pontos <input id="node-size" aria-label="Tamanho dos pontos" type="range" min="4" max="16" value="${prefs.size}"></label><button class="plain-button" id="reset-layout">Reorganizar pontos</button><span>Arraste pontos · role para ampliar · clique para selecionar</span></div><div class="universe-stage"><svg id="universe-svg" viewBox="0 0 1000 600" aria-label="Mapa interativo de conexões"><g id="universe-camera"><g id="universe-edges"></g><g id="universe-nodes"></g></g></svg><div class="universe-selection" id="universe-selection"><span>Selecione um ponto para abrir a nota ou definir sua cor.</span></div><div class="universe-zoom"><button data-universe-zoom="out" aria-label="Diminuir zoom">−</button><button data-universe-zoom="reset" aria-label="Centralizar mapa">1:1</button><button data-universe-zoom="in" aria-label="Aumentar zoom">+</button></div>${!docs.length?`<div class="universe-empty">${discovery.indexing?'Lendo os arquivos do projeto…':'Nenhuma nota corresponde aos filtros.'}</div>`:''}${total>500?'<div class="graph-limit">Exibindo 500 pontos. Refine a busca para explorar os demais.</div>':''}</div><div class="universe-foot">${queryHelp()}<span>Cor no Markdown: <code>color: "#78e2df"</code></span></div></section>`;
 const positions=new Map(docs.map((d,i)=>{const a=i*2.399963,r=docs.length<2?0:Math.min(240,35+Math.sqrt(i)*240/Math.sqrt(docs.length));return [docId(d),prefs.positions[docId(d)]||{x:500+Math.cos(a)*r*1.5,y:290+Math.sin(a)*r}]}));
 $('#universe-edges').innerHTML=edges.map((e,i)=>`<line data-edge="${i}" pathLength="1" style="--delay:${Math.min(i*35,1000)}ms;stroke-width:${prefs.width}"/>`).join('');
 $('#universe-nodes').innerHTML=docs.map(d=>`<g class="universe-node ${discovery.selected===docId(d)?'selected':''}" data-node="${esc(docId(d))}" tabindex="0" role="button" aria-label="Selecionar ${esc(d.title)}"><circle r="${prefs.size}" style="fill:${AmagoSearch.metadata(d.body).color||'#78e2df'}"/><circle class="node-halo" r="${+prefs.size+6}"/><text y="${+prefs.size+24}" text-anchor="middle">${esc((d.title||d.name).slice(0,34))}</text></g>`).join('');
 const draw=()=>{for(const node of document.querySelectorAll('.universe-node')){const p=positions.get(node.dataset.node);node.setAttribute('transform',`translate(${p.x} ${p.y})`)}for(const line of document.querySelectorAll('[data-edge]')){const e=edges[+line.dataset.edge],a=positions.get(e.a),b=positions.get(e.b);for(const [k,v] of Object.entries({x1:a.x,y1:a.y,x2:b.x,y2:b.y}))line.setAttribute(k,v)}};draw();
 const svg=$('#universe-svg'),camera=$('#universe-camera'),apply=()=>camera.setAttribute('transform',`translate(${graphPan.x} ${graphPan.y}) scale(${graphPan.zoom})`);apply();let drag=null;
 const point=e=>{const p=new DOMPoint(e.clientX,e.clientY);return p.matrixTransform(svg.getScreenCTM().inverse())};
 svg.onpointerdown=e=>{if(e.button!==0)return;const p=point(e),node=e.target.closest('[data-node]');drag={id:node?.dataset.node,start:p,last:p,moved:false};svg.setPointerCapture(e.pointerId)};
 svg.onpointermove=e=>{if(!drag)return;const p=point(e);if(Math.hypot(p.x-drag.start.x,p.y-drag.start.y)>4)drag.moved=true;if(!drag.moved)return;if(drag.id){const previous=positions.get(drag.id);positions.set(drag.id,{x:previous.x+(p.x-drag.last.x)/graphPan.zoom,y:previous.y+(p.y-drag.last.y)/graphPan.zoom});draw()}else{graphPan.x+=p.x-drag.last.x;graphPan.y+=p.y-drag.last.y;apply()}drag.last=p};
 const endDrag=()=>{if(drag?.id&&drag.moved){prefs.positions[drag.id]=positions.get(drag.id);persist()}if(drag&&!drag.moved&&drag.id){discovery.selected=drag.id;selectGraphNode()}drag=null};svg.onpointerup=endDrag;svg.onpointercancel=endDrag;
 svg.onwheel=e=>{e.preventDefault();const p=point(e),z=Math.min(4,Math.max(.3,graphPan.zoom*Math.exp(-e.deltaY*.001)));graphPan.x=p.x-(p.x-graphPan.x)*z/graphPan.zoom;graphPan.y=p.y-(p.y-graphPan.y)*z/graphPan.zoom;graphPan.zoom=z;apply()};
 svg.onkeydown=e=>{const node=e.target.closest('[data-node]');if(node&&['Enter',' '].includes(e.key)){e.preventDefault();discovery.selected=node.dataset.node;selectGraphNode()}};
 document.querySelectorAll('[data-universe-zoom]').forEach(b=>b.onclick=()=>{if(b.dataset.universeZoom==='reset')graphPan={x:0,y:0,zoom:1};else graphPan.zoom=Math.min(4,Math.max(.3,graphPan.zoom*(b.dataset.universeZoom==='in'?1.2:1/1.2)));apply()});
 $('#graph-query').oninput=e=>{discovery.graphQuery=e.target.value;const start=e.target.selectionStart;renderUniverse();$('#graph-query').focus();$('#graph-query').setSelectionRange(start,start)};
 $('#use-sidebar-query').onclick=()=>{discovery.graphQuery=workbench.query;renderUniverse()};$('#linked-only').onchange=e=>{discovery.linked=e.target.checked;renderUniverse()};
 $('#edge-width').oninput=e=>{prefs.width=+e.target.value;document.querySelectorAll('[data-edge]').forEach(line=>line.style.strokeWidth=prefs.width)};$('#edge-width').onchange=persist;
 $('#node-size').oninput=e=>{prefs.size=+e.target.value;document.querySelectorAll('.universe-node').forEach(g=>{g.children[0].setAttribute('r',prefs.size);g.children[1].setAttribute('r',prefs.size+6);g.children[2].setAttribute('y',prefs.size+24)})};$('#node-size').onchange=persist;
 $('#reset-layout').onclick=()=>{prefs.positions={};graphPan={x:0,y:0,zoom:1};persist();renderUniverse()};selectGraphNode();
 $('#connection-count').textContent=edges.length+' vínculos visíveis';$('#word-count').textContent=docs.length+' notas no mapa';$('#reading-time').textContent='Layout salvo localmente';
}
function selectGraphNode(){const doc=discoveryDocs().find(d=>docId(d)===discovery.selected),holder=$('#universe-selection');if(!holder)return;document.querySelectorAll('.universe-node').forEach(g=>g.classList.toggle('selected',g.dataset.node===discovery.selected));if(!doc)return;holder.innerHTML=`<strong>${esc(doc.title||doc.name)}</strong><button class="plain-button" id="open-graph-note">Abrir nota ↗</button><label>Cor <input type="color" id="graph-color" aria-label="Cor da nota no Markdown" value="${AmagoSearch.metadata(doc.body).color||'#78e2df'}"></label><small>A cor é gravada no Markdown.</small>`;$('#open-graph-note').onclick=()=>workbench.source==='project'?openProjectFile(doc.path):openNote(doc.id);$('#graph-color').onchange=async e=>{const color=e.target.value;if(workbench.source==='project'){if(!(await saveProjectFile()))return;const read=await window.projectAdapter.read(doc.path);if(read.error){toast(read.error);return}const body=AmagoSearch.withColor(read.body,color),result=await window.projectAdapter.save(doc.path,body,read.version);if(result.error||result.conflict){toast(result.error||'O arquivo mudou. Atualize o projeto antes de tentar novamente.');return}doc.body=body;doc.version=result.version;if(workbench.file?.path===doc.path)Object.assign(workbench.file,{body,savedBody:body,version:result.version,dirty:false})}else{doc.body=AmagoSearch.withColor(doc.body,color);doc.updated=stamp();persist()}renderUniverse()}}
const universeMain=renderMain;
renderMain=function(){if(state.view==='graph'){renderUniverse();return}universeMain()};
document.addEventListener('click',e=>{const open=e.target.closest('[data-open-universe]');if(open){e.preventDefault();e.stopImmediatePropagation();state.view='graph';state.tag=null;render();if(!discovery.docs.length)indexProject();return}const remove=e.target.closest('[data-remove-filter]');if(remove){e.preventDefault();e.stopImmediatePropagation();const graph=!!remove.closest('#graph-chips'),key=graph?'graphQuery':'query',holder=graph?discovery:workbench;holder[key]=AmagoSearch.tokens(holder[key]).filter((_,i)=>i!==+remove.dataset.removeFilter).map(t=>t.raw).join(' ');graph?renderUniverse():renderTree()}},true);
renderTree();

search=actions.search=()=>{workbench.tab='search';renderTree();$('#side-query')?.focus()};

const saveWithIndex=saveProjectFile;
saveProjectFile=async()=>{const file=workbench.file;const ok=await saveWithIndex();if(ok&&file?.kind==='markdown'){file.size=new TextEncoder().encode(file.body).length;const indexed=discovery.docs.find(d=>d.path===file.path);if(indexed)Object.assign(indexed,{body:file.body,version:file.version,updated:new Date().toISOString()})}return ok};
workActions.save=saveProjectFile;
